-- Migration 004: Hierarchical Locations (PostgreSQL)
BEGIN;

CREATE TABLE IF NOT EXISTS countries (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  code TEXT UNIQUE NOT NULL
);

CREATE TABLE IF NOT EXISTS states (
  id TEXT PRIMARY KEY,
  country_id TEXT NOT NULL REFERENCES countries(id) ON DELETE CASCADE,
  name TEXT NOT NULL,
  code TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_states_country_id ON states(country_id);

CREATE TABLE IF NOT EXISTS districts (
  id TEXT PRIMARY KEY,
  state_id TEXT NOT NULL REFERENCES states(id) ON DELETE CASCADE,
  name TEXT NOT NULL,
  code TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_districts_state_id ON districts(state_id);

CREATE TABLE IF NOT EXISTS talukas (
  id TEXT PRIMARY KEY,
  district_id TEXT NOT NULL REFERENCES districts(id) ON DELETE CASCADE,
  name TEXT NOT NULL,
  code TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_talukas_district_id ON talukas(district_id);

CREATE TABLE IF NOT EXISTS villages (
  id TEXT PRIMARY KEY,
  taluka_id TEXT NOT NULL REFERENCES talukas(id) ON DELETE CASCADE,
  name TEXT NOT NULL,
  code TEXT
);
CREATE INDEX IF NOT EXISTS idx_villages_taluka_id ON villages(taluka_id);
CREATE INDEX IF NOT EXISTS idx_villages_name ON villages(name);

ALTER TABLE members ADD COLUMN IF NOT EXISTS country_id TEXT;
ALTER TABLE members ADD COLUMN IF NOT EXISTS state_id TEXT;
ALTER TABLE members ADD COLUMN IF NOT EXISTS district_id TEXT;
ALTER TABLE members ADD COLUMN IF NOT EXISTS taluka_id TEXT;
ALTER TABLE members ADD COLUMN IF NOT EXISTS village_id TEXT;
ALTER TABLE members ADD COLUMN IF NOT EXISTS taluka TEXT;
ALTER TABLE members ADD COLUMN IF NOT EXISTS village TEXT;

